import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-03-29","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-03-29","date":"2022-03-29T00:00:00.000Z","updated":"2022-03-31T00:00:00.000Z","tags":["Ceph","分布式存储","vstart","NFS","开发工具"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-03-29.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-03-29.md","lastUpdated":1780460162000}'),s={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-03-29.md"};function o(i,t,n,h,d,g){return r(),e("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Ceph vstart 依赖性问题</strong></p><ul><li><strong>问题描述</strong>：在启用 self adm 时，vstart 无法加载 self adm 的依赖项，导致启动失败。</li><li><strong>讨论内容</strong>：会议讨论了是否将依赖项作为构建请求的一部分添加，但认为这些依赖项并非严格意义上的构建依赖。</li><li><strong>解决方案</strong>：短期解决方案为异常处理和模拟，长期解决方案需进一步研究 vstart 如何处理运行时依赖。</li></ul></li><li><p><strong>Ceph 开发工具的使用</strong></p><ul><li><strong>讨论内容</strong>：讨论了开发人员使用的工具，如 kcli 和容器化方法，以及 vstart 使用频率较低导致问题未及时发现。</li></ul></li><li><p><strong>Ceph NFS相关问题</strong></p><ul><li><strong>问题描述</strong>：讨论了NFS服务的部署问题，特别是多个NFS守护进程在同一主机上的部署问题，以及NFS服务的高可用性配置。</li><li><strong>解决方案</strong>：提出了一些改进措施，如改进端口冲突解决机制。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li><strong>vstart依赖性问题</strong>：短期内采用异常处理和模拟方法解决，长期需找到合适的运行时依赖管理机制。</li><li><strong>NFS部署问题</strong>：需要进一步研究和测试NFS服务的部署和运行机制，特别是高可用性和端口冲突问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>vstart依赖性问题</strong>：继续研究vstart的依赖管理，寻找更合适的解决方案。</li><li><strong>NFS部署问题</strong>：创建跟踪票，进一步研究NFS服务的部署和运行机制。</li><li><strong>开发工具使用</strong>：鼓励团队成员更多地使用vstart等开发工具，以便及时发现和解决问题。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了开发人员通常使用的工具，如kcli和容器化方法，以及vstart的使用频率较低。</li><li>讨论了NFS服务的部署问题，特别是多个NFS守护进程在同一主机上的部署问题，以及NFS服务的高可用性配置。</li></ul><h4 id="结论" tabindex="-1">结论： <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论：&quot;">​</a></h4><p>会议主要解决了Ceph vstart的依赖性问题和NFS服务的部署问题，并提出了相应的短期和长期解决方案。后续将继续研究和测试相关问题，确保Ceph的稳定性和可靠性。</p>',11)])])}const _=a(s,[["render",o]]);export{c as __pageData,_ as default};
